SELECT id, customer_id, account_type, balance, opened_date, AVG(balance) OVER (ORDER BY opened_date ASC, id ASC ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS balance_avg_5, ROW_NUMBER() OVER (PARTITION BY YEAR(opened_date), status ORDER BY balance ASC, id ASC) AS seq_no, LAST_VALUE(balance, TRUE) OVER (PARTITION BY account_type ORDER BY balance ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_balance FROM accounts;
